#!/usr/bin/env python3
"""ID ringkasan strings for Digital_Technic_Micro, meetings 10-13, one per
TOPICAL slide in document order, matching extract_slides.topical_spans()."""

RINGKASAN = {}

RINGKASAN[10] = [
 r"Pertemuan 1--8 membangun model mikrokomputer secara konseptual (CPU, bus, memori); pertemuan 10--17 melihat blok fisik: IC yang mengimplementasikan unit-unit itu, dan display yang menghubungkan mikrokomputer dengan manusia -- dimulai dari definisi IC dan cara mengklasifikasikannya.",
 r"IC (integrated circuit) memadatkan banyak transistor, resistor, dan interkoneksinya dalam satu keping semikonduktor (biasanya silikon), menggantikan komponen diskrit yang dulu dirangkai terpisah di papan; dibuat lewat fotolitografi hingga miliaran perangkat per chip.",
 r"Skala integrasi diurutkan dari SSI (1--10 gerbang, mis.\ NAND quad 7400), MSI (10--100 gerbang: counter, decoder, multiplexer), LSI (100--10.000 gerbang: mikroprosesor awal), hingga VLSI ($>10.000$ gerbang: mikroprosesor dan chip memori modern); ULSI ($>1$ juta gerbang) kadang ditambahkan untuk chip paling kompleks.",
 r"Sejarah: 1960-an SSI (segelintir gerbang per chip), 1970-an MSI/LSI (mikroprosesor pertama seperti Intel 4004, 8085), 1980-an dst VLSI (jutaan transistor); tiap lompatan kira-kira mengikuti Hukum Moore -- jumlah transistor per chip berlipat ganda tiap sekitar dua tahun.",
 r"Integrasi penting karena ukuran/berat (krusial di avionik, tiap gram memengaruhi bahan bakar dan payload), daya lebih rendah, biaya per fungsi lebih murah (biaya fabrikasi dibagi jutaan gerbang), dan keandalan lebih tinggi (lebih sedikit sambungan solder/kabel eksternal, lebih sedikit titik kegagalan).",
 r"Untuk mengklasifikasi skala sebuah chip, perkirakan jumlah gerbang setaranya dari fungsinya: satu paket gerbang logika (mis.\ 74LS08 quad AND) $\to$ SSI; counter 4-bit atau multiplexer 8:1 $\to$ MSI; mikroprosesor 8-bit $\to$ LSI; CPU 64-bit modern atau chip memori gigabyte $\to$ VLSI.",
 r"Integrasi tinggi bukan tanpa biaya: cacat fabrikasi meningkat seiring luas die sehingga chip sangat besar bisa punya yield produksi lebih rendah; debugging/pengujian internal VLSI jauh lebih sulit daripada menguji gerbang SSI langsung dengan probe; chip VLSI yang rusak hanya bisa diganti, bukan diperbaiki di level transistor.",
 r"Kesalahan umum: menganggap batas skala sebagai angka pasti padahal hanya perkiraan orde besaran; mengira jumlah pin sama dengan jumlah gerbang padahal chip berpin sedikit bisa berisi banyak gerbang internal (mis.\ mikroprosesor); tertukar urutan SSI (paling sederhana) dan VLSI (paling kompleks).",
 r"Soal: definisikan SSI, MSI, LSI, dan VLSI beserta rentang jumlah gerbang perkiraannya.",
 r"SSI: 1--10 gerbang. MSI: 10--100 gerbang. LSI: 100--10.000 gerbang. VLSI: $>10.000$ gerbang.",
 r"Soal: jelaskan dua manfaat integrasi tinggi khusus untuk peralatan avionik.",
 r"(1) Ukuran dan berat berkurang -- langsung meningkatkan efisiensi bahan bakar dan kapasitas payload pesawat. (2) Keandalan meningkat -- lebih sedikit sambungan solder diskrit dan kabel eksternal berarti lebih sedikit titik potensi kegagalan pada sistem flight-critical.",
 r"Soal: klasifikasikan mikroprosesor 64-bit modern menurut skala integrasi, dan jelaskan alasannya.",
 r"VLSI (bahkan sering disebut ULSI). CPU 64-bit modern berisi ratusan juta hingga miliaran transistor -- jauh melampaui ambang $>10.000$ gerbang untuk VLSI.",
 r"Soal: satu chip berisi empat gerbang AND 2-input independen dan tidak ada lagi. Skala integrasi apa ini, dan mengapa desainer mungkin tetap memilih chip sesederhana ini hari ini?",
 r"Ini SSI (paket quad-AND seri 74 klasik, sekitar 4 gerbang). Desainer tetap memakai SSI sebagai glue logic untuk fungsi sederhana dan terisolasi (mis.\ satu gerbang AND tambahan untuk sinyal enable) agar tidak perlu memakai perangkat VLSI terprogram yang berlebihan biaya dan kompleksitasnya.",
]

RINGKASAN[11] = [
 r"Logic family adalah sekumpulan IC yang dibangun dengan teknologi transistor dan konvensi elektrik yang sama, sehingga komponen dalam satu keluarga bisa langsung saling terhubung; dua keluarga dominan di mata kuliah ini adalah TTL dan CMOS -- pilihan keluarga memengaruhi kecepatan, konsumsi daya, kekebalan noise, dan cara antarmuka dengan chip lain.",
 r"TTL dibangun dari transistor bipolar (BJT): switching cepat, tetapi menarik arus statis terus-menerus bahkan saat idle sehingga konsumsi daya lebih tinggi dari CMOS; suplai standar 5V $\pm5\%$; dominan secara historis (seri 7400) dari 1960-an--1980-an.",
 r"CMOS dibangun dari pasangan MOSFET komplementer (satu PMOS, satu NMOS per gerbang): daya statis sangat rendah karena arus mengalir terutama saat switching; kepadatan transistor lebih tinggi dari TTL untuk luas die yang sama -- kunci penskalaan VLSI; rentang tegangan suplai lebar (historis 3--15V, CMOS modern sering 1,8--5V).",
 r"Perbandingan ringkas: daya statis TTL tinggi vs CMOS sangat rendah; daya dinamis TTL sedang vs CMOS naik seiring frekuensi switching; kecepatan keduanya cepat pada proses modern; noise margin TTL sedang vs CMOS tinggi; suplai TTL tetap 5V vs CMOS rentang lebar; kepadatan TTL lebih rendah vs CMOS lebih tinggi.",
 r"$V_{IH}$/$V_{IL}$ adalah tegangan input HIGH minimum / LOW maksimum yang masih dikenali gerbang secara andal; $V_{OH}$/$V_{OL}$ adalah tegangan output HIGH/LOW yang dijamin dihasilkan gerbang; noise margin $=V_{OH}-V_{IH}$ (sisi tinggi) atau $V_{IL}-V_{OL}$ (sisi rendah) -- seberapa besar noise yang bisa ditoleransi sebelum sinyal salah dibaca; CMOS umumnya punya noise margin lebih lebar dari TTL, lebih tangguh di lingkungan bising seperti sistem listrik pesawat.",
 r"Fan-out adalah jumlah maksimum input standar yang dapat digerakkan secara andal oleh satu output, dibatasi oleh arus drive output dibanding arus yang dibutuhkan tiap input; output TTL membatasi fan-out karena arus sink/source terbatas, sedangkan input CMOS hampir tidak menarik arus statis sehingga fan-out CMOS sangat tinggi -- meski switching cepat tetap membebani output lewat kapasitansi.",
 r"Selalu cocokkan level logika ($V_{IH}/V_{IL}$, $V_{OH}/V_{OL}$) antara keluarga pengirim dan penerima sebelum menghubungkan langsung; gunakan IC level shifter/translator bila tegangan suplai berbeda signifikan; input CMOS tidak boleh dibiarkan mengambang -- input CMOS yang tidak digerakkan bisa berada di tegangan menengah, menyalakan PMOS dan NMOS sekaligus dan menyebabkan penarikan arus berlebih; ikat input CMOS yang tak terpakai ke $V_{CC}$ atau GND lewat pull-up/pull-down.",
 r"Kesalahan umum: mengira semua chip ``logika 5V'' otomatis kompatibel padahal harus selalu memeriksa ambang $V_{IH}/V_{IL}$, bukan hanya tegangan suplai; membiarkan input CMOS yang tak terpakai mengambang karena dianggap ``tidak penting''; lupa bahwa daya dinamis CMOS justru naik seiring frekuensi switching, berbeda dari daya statisnya yang mendekati nol.",
 r"Soal: sebutkan dua perbedaan antara TTL dan CMOS.",
 r"(1) TTL memakai transistor bipolar dan menarik arus statis terus-menerus; CMOS memakai MOSFET komplementer dengan daya statis sangat rendah. (2) TTL punya suplai tetap 5V; CMOS beroperasi pada rentang tegangan suplai yang jauh lebih lebar.",
 r"Soal: mengapa input CMOS tidak boleh dibiarkan mengambang?",
 r"Input CMOS yang mengambang bisa menetap pada tegangan menengah yang menyalakan sebagian PMOS dan NMOS pada tahap input secara bersamaan, menyebabkan penarikan arus berlebih (dan tidak terduga) serta kemungkinan ambiguitas level logika.",
 r"Soal: sebutkan satu alasan CMOS mendominasi IC modern dibanding TTL.",
 r"Konsumsi daya statis CMOS yang sangat rendah dan kepadatan transistor yang lebih tinggi memungkinkan jauh lebih banyak gerbang dipadatkan dalam satu chip (skala VLSI/ULSI) tanpa panas atau tarikan daya berlebih -- sesuatu yang tidak bisa dicapai TTL bipolar pada level integrasi yang sama.",
 r"Soal: output TTL 5V ($V_{OH,min}=2{,}4$V) menggerakkan input CMOS yang membutuhkan $V_{IH,min}=3{,}5$V. Apakah antarmuka ini akan bekerja andal, dan apa yang harus dilakukan jika tidak?",
 r"Tidak -- HIGH minimum yang dijamin output TTL ($2{,}4$V) berada di bawah ambang HIGH yang dibutuhkan input CMOS ($3{,}5$V), sehingga gerbang CMOS mungkin tidak selalu membaca HIGH dengan andal. Solusi: tambahkan resistor pull-up ke $V_{CC}$ pada output TTL, atau gunakan IC buffer/translator level-shifting TTL-ke-CMOS khusus.",
]

RINGKASAN[12] = [
 r"Memilih IC yang tepat untuk sebuah desain bukan sekadar mencocokkan fungsi logikanya -- IC itu juga harus bertahan dan bekerja benar dalam batas listrik yang tercantum; setiap parameter pada pertemuan ini langsung berasal dari datasheet pabrikan, dan salah membaca angka-angka ini bisa merusak chip atau membuat rangkaian tidak andal di lapangan.",
 r"Absolute maximum ratings mencakup rentang dan toleransi tegangan suplai (mis.\ $5\text{V}\pm5\%$), tegangan input maksimum, arus output maksimum, disipasi daya maksimum, serta rentang suhu penyimpanan dan operasi -- melampaui batas maksimum absolut mana pun, walau sesaat, berisiko merusak chip secara permanen karena ini bukan ``rekomendasi'' melainkan batas keras.",
 r"$V_{IH}$ = tegangan input minimum yang dibaca sebagai HIGH; $V_{IL}$ = tegangan input maksimum yang dibaca sebagai LOW; $V_{OH}$ = tegangan output HIGH minimum yang dijamin; $V_{OL}$ = tegangan output LOW maksimum yang dijamin; noise margin (tinggi) $=V_{OH}-V_{IH}$, noise margin (rendah) $=V_{IL}-V_{OL}$.",
 r"$I_{OH}$ adalah arus yang bisa disuplai (source) output sambil tetap di atas $V_{OH}$; $I_{OL}$ adalah arus yang bisa diserap (sink) output sambil tetap di bawah $V_{OL}$; disipasi daya $P=V_{CC}\times I_{CC}$ (ditambah rugi switching) menentukan panas yang dihasilkan dan kebutuhan pendinginan/derating.",
 r"Propagation delay ($t_{PD}$) adalah waktu dari perubahan input yang valid hingga perubahan output yang bersesuaian; membatasi frekuensi clock maksimum yang bisa dicapai rangkaian dari gerbang tersebut; diberikan sebagai $t_{PLH}$ (low-ke-high) dan $t_{PHL}$ (high-ke-low), datasheet biasanya mencantumkan nilai yang lebih besar sebagai batas desain; delay gerbang yang dikaskade akan terakumulasi -- krusial untuk anggaran waktu desain sinkron.",
 r"Fan-out = berapa banyak input standar yang bisa digerakkan andal satu output tanpa melanggar jaminan $V_{OH}/V_{OL}$, dihitung dari nilai minimum antara $I_{OH}/I_{IH}$ dan $I_{OL}/I_{IL}$; melebihi fan-out menurunkan margin tegangan output dan bisa menyebabkan kesalahan logika saat dibebani.",
 r"Jenis kemasan IC: DIP (through-hole, mudah untuk prototyping), SOIC (surface-mount, kompak), QFP (banyak pin di keempat sisi, pipih), BGA (bola solder di bawah chip, kepadatan tertinggi); kemasan padat (QFP, BGA) cocok untuk chip VLSI berpin banyak, sedangkan DIP cocok untuk pin sedikit dan prototyping yang mudah disolder/disoket.",
 r"Pemilihan kemasan untuk avionik: getaran dan siklus termal lebih cocok dengan kemasan yang mudah disolder dan didukung baik; VLSI berpin banyak (mikroprosesor, FPGA) biasanya memaksa penggunaan BGA atau QFP; kemudahan perbaikan dan inspeksi kadang lebih memilih kemasan besar dengan kaki terlihat bila pilihan masih terbuka.",
 r"Soal: definisikan fan-out dan propagation delay.",
 r"Fan-out: jumlah maksimum input logika standar yang dapat digerakkan andal satu output sambil tetap memenuhi jaminan $V_{OH}/V_{OL}$-nya. Propagation delay: waktu antara perubahan input yang valid dan perubahan output yang dihasilkan pada sebuah gerbang.",
 r"Soal: sebutkan keempat tegangan ambang logika dan apa yang masing-masing wakili.",
 r"$V_{IH}$ -- tegangan input minimum yang dibaca HIGH. $V_{IL}$ -- tegangan input maksimum yang dibaca LOW. $V_{OH}$ -- tegangan output HIGH minimum yang dijamin. $V_{OL}$ -- tegangan output LOW maksimum yang dijamin.",
 r"Soal: sebutkan kemasan yang cocok untuk chip VLSI berpin banyak, dan jelaskan mengapa DIP tidak cocok di sana.",
 r"BGA (atau QFP) cocok untuk chip VLSI berpin banyak karena pin/bolanya bisa dipadatkan di bawah atau sekeliling seluruh footprint chip. DIP tidak cocok pada jumlah pin tinggi karena dua barisnya yang hanya di dua sisi akan membuat kemasan menjadi terlalu panjang secara tidak praktis.",
 r"Soal: sebuah gerbang memiliki $I_{OH}=400\,\mu A$ dan setiap input yang terhubung membutuhkan $I_{IH}=40\,\mu A$. Berapa batas fan-out dari sisi arus HIGH saja?",
 r"Fan-out $=I_{OH}/I_{IH}=400/40=10$. Output dapat menggerakkan andal hingga 10 input standar sebelum jaminan $V_{OH}$ terancam (batas sisi LOW juga harus diperiksa dan nilai yang lebih kecil dari keduanya yang dipakai).",
]

RINGKASAN[13] = [
 r"Pertemuan 10--12 memberikan kosakata (skala integrasi, logic family, karakteristik elektrik); pertemuan lab ini menerapkannya secara langsung dan praktis -- setiap pemilihan komponen dalam perawatan dan desain avionik nyata dimulai dari membaca datasheet pabrikan dengan benar, dan salah membaca datasheet adalah salah satu penyebab paling umum kegagalan di lapangan dan pekerjaan ulang.",
 r"Struktur datasheet: deskripsi fungsional dan diagram blok (fungsi internal chip), konfigurasi pin/pinout (penempatan pin fisik), absolute maximum ratings (batas bertahan keras, Pertemuan 12), recommended operating conditions (rentang aman untuk operasi normal, lebih sempit dari maksimum absolut), electrical characteristics ($V_{IH}/V_{IL}/V_{OH}/V_{OL}$, arus, daya), dan timing characteristics (propagation delay, waktu setup/hold).",
 r"Identifikasi $V_{CC}$ (daya), GND (ground), input, dan output dari diagram pin; contoh: 74LS08 (quad AND 2-input) berpin 14 -- pin 14 = $V_{CC}$, pin 7 = GND, dan empat gerbang AND independen menempati 12 pin sisanya (2 input + 1 output tiap gerbang); pin 1 biasanya ditandai takik atau titik pada kemasan sebagai penanda orientasi.",
 r"Absolute maximum (mis.\ suplai $-0{,}5$ hingga $7$V) adalah batas yang tidak boleh dilewati sama sekali karena berisiko merusak chip, sedangkan recommended operating conditions (mis.\ $4{,}75$--$5{,}25$V) adalah target desain normal; mendesain di tepi rentang rekomendasi masih menyisakan margin sebelum menyentuh maksimum absolut -- praktik baik untuk keandalan.",
 r"Contoh pembacaan tabel karakteristik elektrik TTL pada $V_{CC}=5$V, $25^{\circ}$C: $V_{IH}$(min) 2,0V, $V_{IL}$(max) 0,8V, $V_{OH}$(min) 2,4V, $V_{OL}$(max) 0,4V -- keempat angka ini saja sudah cukup untuk memeriksa kompatibilitas antarmuka (Pertemuan 11).",
 r"Contoh bagian timing datasheet: $t_{PLH}=15$ns, $t_{PHL}=12$ns untuk sebuah gerbang; gunakan nilai yang lebih besar sebagai propagation delay terburuk untuk anggaran waktu; untuk komponen sekuensial (flip-flop), periksa juga waktu setup ($t_{su}$) dan hold ($t_h$) relatif terhadap tepi clock.",
 r"Checklist verifikasi kesesuaian komponen: (1) pastikan tegangan suplai cocok dengan rel yang tersedia pada desain, (2) periksa kompatibilitas level logika dengan chip tetangga ($V_{IH}/V_{IL}$ vs $V_{OH}/V_{OL}$), (3) pastikan arus drive ($I_{OH}/I_{OL}$) memenuhi kebutuhan fan-out/beban, (4) pastikan propagation delay memenuhi laju clock yang dibutuhkan desain, (5) pastikan rentang suhu operasi mencakup lingkungan aplikasi.",
 r"Kesalahan umum: membaca nilai ``typical'' sebagai jaminan padahal desain harus selalu mengacu kolom ``min''/``max'' untuk operasi andal di seluruh variasi manufaktur; tertukar antara nomor pin (lokasi fisik) dengan nama/fungsi pin; mengabaikan rentang suhu -- komponen grade komersial $0$--$70^{\circ}$C mungkin tidak bertahan di lingkungan avionik yang membutuhkan grade extended/militer.",
 r"Soal: identifikasi pin $V_{CC}$ dan GND dari 74LS08 (quad AND 2-input, 14 pin).",
 r"Pin 14 = $V_{CC}$ (daya). Pin 7 = GND (ground) -- penempatan diagonal standar yang dipakai di seluruh keluarga DIP 14-pin seri 74.",
 r"Soal: sebutkan urutan bagian datasheet yang perlu diperiksa untuk memilih IC gerbang pada desain baru.",
 r"(1) Deskripsi fungsional/diagram blok -- memastikan fungsi logikanya benar. (2) Pinout -- memastikan jumlah dan tata letak pin cocok dengan papan. (3) Recommended operating conditions -- memastikan tegangan suplai cocok. (4) Electrical characteristics -- memastikan kompatibilitas level logika dan arus. (5) Timing characteristics -- memastikan kecepatan memenuhi laju clock desain.",
 r"Soal: jelaskan mengapa absolute maximum ratings tidak boleh dilampaui, bahkan sesaat.",
 r"Absolute maximum ratings menetapkan batas fisik/listrik keras yang di luarnya silikon atau kemasan bisa mengalami kerusakan permanen (mis.\ junction breakdown, kerusakan termal). Berbeda dari recommended operating conditions, tidak ada ``margin'' di luar maksimum absolut -- melampauinya berisiko kegagalan langsung atau laten (tertunda).",
 r"Soal: sebuah datasheet mencantumkan suhu operasi chip $0^\circ$C hingga $70^\circ$C (grade komersial). Apakah ini cocok untuk ruang avionik pesawat, dan apa yang seharusnya diperiksa sebagai gantinya?",
 r"Belum tentu cocok -- ruang avionik bisa mengalami suhu ekstrem yang lebih lebar daripada yang dijamin komponen grade komersial. Periksa datasheet untuk versi grade industrial ($-40^\circ$C hingga $85^\circ$C) atau grade militer/aerospace ($-55^\circ$C hingga $125^\circ$C) dari komponen yang sama.",
]
